export const maxCopies = (id) => (RARE_RACE.has(id) || LEGENDARY.has(id) || MYTHIC.has(id) ? 1 : raceOf(id) ? 2 : ({ 5: 1, 14: 1, 187: 2, 46: 2, 47: 2, 48: 2, 49: 1, 123: 2, 124: 2, 127: 2, 128: 2, 155: 2, 163: 2, 164: 2, 165: 1 }[id] ?? 3));
