export const NCARDS = 188; // + Trueque (187, neutral) y Golpe de sombra (188, drow), Juan 28/10 — antes: // 1-179 como siempre (49 originales, 12 neutrales, 60 de raza, 8 de rey, 18 de favor, 32 tácticas) + 6 míticas (180-185) + Ojo del vigía (186, ver trampas)
export const NCARDS_ALL = Math.max(...Object.keys(CAMPAIGN_CARDS).map(Number)); // último id con las cartas de campaña (190+); los mazos de campaña usan este largo
// Cartas raras: una sola copia en el mazo. Espía y Sabotaje no descuentan su costo (como en el original).
export const RARE = new Set([5, 14, 49]); // Peste rara, 1 copia (Juan 27/10)
export function kindOf(id){const c=CARDS[id][0];const n=[c[1],c[3],c[5]].filter(x=>x>0).length;
  if(c[8]&&n===0)return 'favor'; if(n>1)return 'mixed'; if(c[1])return 'brick'; if(c[3])return 'weapon'; if(c[5])return 'crystal';
  if(c[0])return 'brick'; if(c[2])return 'weapon'; if(c[4])return 'crystal'; return 'mixed';}
